use observability::error::{CafError, WrapErrorInResult};
use std::{path::Path, time::Duration};
use tokio::net::UnixListener;
use tokio_stream::wrappers::UnixListenerStream;
use tonic::{
    Request, Status,
    transport::{Channel, Endpoint},
};

use crate::protocol::{
    cli_service_client::CliServiceClient,
    cli_service_server::{CliService, CliServiceServer},
};

// Include the Rust code generated by tonic-build from cli.proto
pub mod protocol {
    tonic::include_proto!("cli");
}

const CLI_SOCKET_PATH: &str = "/tmp/caf.sock";

type InterceptorFn = fn(Request<()>) -> Result<Request<()>, Status>;

pub async fn setup_server(
    cli_server: impl CliService,
    interceptors: Vec<InterceptorFn>,
) -> Result<(), CafError> {
    let path = Path::new(CLI_SOCKET_PATH);

    if path.exists() {
        tokio::fs::remove_file(path)
            .await
            .wrap_err("unable to clean the cli socket")?;
    }

    let listener = UnixListener::bind(path).wrap_err("unable create the cli server listener")?;

    let stream = UnixListenerStream::new(listener);

    let composite_interceptor = move |req: Request<()>| -> Result<Request<()>, Status> {
        interceptors.iter().try_fold(req, |acc, cur| cur(acc))
    };

    tonic::transport::Server::builder()
        .add_service(CliServiceServer::with_interceptor(
            cli_server,
            composite_interceptor,
        ))
        .serve_with_incoming(stream)
        .await
        .wrap_err("unable to start the cli server")
}

const CLIENT_TIMEOUT: Duration = Duration::from_secs(30);
pub async fn setup_client() -> Result<CliServiceClient<Channel>, CafError> {
    let channel = Endpoint::try_from(format!("unix://{}", CLI_SOCKET_PATH))
        .wrap_err("unable to create endpoint")?
        .connect_timeout(CLIENT_TIMEOUT)
        .connect()
        .await
        .wrap_err("unable to connect to uds")?;

    Ok(CliServiceClient::new(channel))
}
